def extract(root):
    raw = lzma.decompress(base64.b85decode(DATA + TAIL))
    assert hashlib.sha256(raw).hexdigest() == PAYLOAD_SHA256
    for relative, value in json.loads(raw).items():
        path = root / relative
        assert ".." not in path.parts and not relative.startswith("/")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(
            value["text"].encode()
            if "text" in value
            else base64.b64decode(value["base64"])
        )
